{
  "flashcards": [
    {
      "front": "What is the primary goal of query tuning in PostgreSQL?",
      "back": "To identify and optimize slow-running queries using EXPLAIN ANALYZE, focusing on reducing I/O, utilizing appropriate indexes, and avoiding full table scans to improve overall system latency and throughput.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "How do you ensure transactional correctness in a distributed system using PostgreSQL?",
      "back": "Use ACID-compliant transactions, appropriate isolation levels (e.g., READ COMMITTED or SERIALIZABLE), and implement idempotency keys or distributed locking mechanisms to handle race conditions and partial failures effectively.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is the primary benefit of using gRPC over REST for internal service communication?",
      "back": "gRPC uses Protocol Buffers for efficient binary serialization and HTTP/2 for multiplexing, resulting in smaller payloads, faster transmission, and strict contract enforcement via strongly-typed schemas.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "How do you approach mentoring a junior engineer who is struggling with a complex task?",
      "back": "Shift from providing solutions to asking guiding questions. Break the problem into smaller, manageable sub-tasks. Encourage them to document their thought process and review their code with a focus on 'why' rather than just 'how'.",
      "requirement_ids": ["r5"]
    },
    {
      "front": "What is the most effective way to handle an on-call incident for a service you own?",
      "back": "Prioritize mitigation (restoring service) over root cause analysis. Communicate clearly with stakeholders, document the incident timeline, and ensure a post-mortem is conducted to prevent recurrence.",
      "requirement_ids": ["r6"]
    },
    {
      "front": "What is the purpose of a Terraform state file?",
      "back": "It maps your real-world infrastructure resources to your configuration, tracks metadata, and manages dependencies. It is critical for determining which changes need to be applied during the next execution.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "What is the difference between a Kafka topic partition and a consumer group?",
      "back": "A partition is a unit of parallelism within a topic. A consumer group allows multiple consumers to divide the work of reading from these partitions, ensuring each message is processed by only one consumer in the group.",
      "requirement_ids": ["r9"]
    },
    {
      "front": "How do you manage database schema migrations in a high-traffic production environment?",
      "back": "Use backward-compatible migrations. Split breaking changes into multiple steps: add new columns, update code to write to both, backfill data, update code to read from new, then drop old columns.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "What is a common challenge when designing APIs for consumption by other teams?",
      "back": "Maintaining backward compatibility. Always version your APIs (e.g., URL versioning or header versioning) and avoid making breaking changes to existing endpoints to prevent downstream service failures.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "Why is 'eventual consistency' often preferred in logistics or supply chain systems?",
      "back": "Logistics systems often involve distributed physical locations and high latency. Eventual consistency allows high availability and partition tolerance, accepting that data will synchronize across nodes asynchronously rather than requiring immediate, blocking consistency.",
      "requirement_ids": ["r8", "r9"]
    },
    {
      "front": "What is a key advantage of using Node.js for I/O-bound backend services?",
      "back": "Its non-blocking, event-driven architecture allows it to handle many concurrent connections efficiently using a single thread, making it ideal for high-throughput, I/O-intensive applications.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What is the 'sidecar' pattern in Kubernetes?",
      "back": "A pattern where a helper container runs alongside the main application container in the same pod. It shares the same network and storage, often used for logging, proxying, or configuration management.",
      "requirement_ids": ["r7"]
    },
    {
      "front": "How do you define 'production readiness' for a backend service?",
      "back": "It includes robust logging, structured monitoring/alerting, automated testing, CI/CD pipelines, documented runbooks for on-call, and clear capacity planning to handle expected traffic loads.",
      "requirement_ids": ["r1", "r6"]
    },
    {
      "front": "What is the primary benefit of using Go's concurrency model (goroutines)?",
      "back": "Goroutines are lightweight threads managed by the Go runtime, allowing thousands of concurrent operations with minimal memory overhead, simplifying complex asynchronous logic compared to traditional OS thread management.",
      "requirement_ids": ["r2"]
    }
  ]
}
